  20|package com.puppycrawl.tools.checkstyle;
  21|
  22|import java.io.IOException;
  23|import java.io.InputStream;
  24|import java.util.Map;
  25|
  26|import javax.xml.parsers.ParserConfigurationException;
  27|import javax.xml.parsers.SAXParserFactory;
  28|
  29|import org.xml.sax.InputSource;
  30|import org.xml.sax.SAXException;
  31|import org.xml.sax.SAXParseException;
  32|import org.xml.sax.XMLReader;
  33|import org.xml.sax.helpers.DefaultHandler;
  34|
  35|/**
  36| * Contains the common implementation of a loader, for loading a configuration from an XML file.
  37| *
  38| * <p>
  39| * The error handling policy can be described as being austere, dead set,
  40| * disciplinary, dour, draconian, exacting, firm, forbidding, grim, hard, hard-
  41| * boiled, harsh, harsh, in line, iron-fisted, no-nonsense, oppressive,
  42| * persnickety, picky, prudish, punctilious, puritanical, rigid, rigorous,
  43| * scrupulous, set, severe, square, stern, stickler, straight, strait-laced,
  44| * stringent, stuffy, stuffy, tough, unpermissive, unsparing and uptight.
  45| * </p>
  46| *
  47| * @noinspection ThisEscapedInObjectConstruction
  48| * @noinspectionreason ThisEscapedInObjectConstruction - only reference is used and not
  49| *      accessed until initialized
  50| */
  51|public class XmlLoader extends DefaultHandler {
  52|
  53|    /** Maps public id to resolve to resource name for the DTD. */
  54|    private final Map<String, String> publicIdToResourceNameMap;
  55|    /** Parser to read XML files. */
  56|    private final XMLReader parser;
  57|
  58|    /**
  59|     * Creates a new instance.
  60|     *
  61|     * @param publicIdToResourceNameMap maps public IDs to DTD resource names
  62|     * @throws ParserConfigurationException if an error occurs
  63|     * @throws SAXException if an error occurs
  64|     */
  65|    protected XmlLoader(Map<String, String> publicIdToResourceNameMap)
  66|            throws SAXException, ParserConfigurationException {
  67|        this.publicIdToResourceNameMap = Map.copyOf(publicIdToResourceNameMap);
  68|        parser = createXmlReader(this);
  69|    }
  70|
  71|    /**
  72|     * Parses the specified input source.
  73|     *
  74|     * @param inputSource the input source to parse.
  75|     * @throws IOException if an error occurs
  76|     * @throws SAXException in an error occurs
  77|     */
  78|    public void parseInputSource(InputSource inputSource)
  79|            throws IOException, SAXException {
  80|        parser.parse(inputSource);
  81|    }
  82|
  83|    @Override
  84|    public InputSource resolveEntity(String publicId, String systemId) {
  85|        InputSource inputSource = null;
  86|        if (publicId != null) {
  87|            final String dtdResourceName = publicIdToResourceNameMap.get(publicId);
  88|
  89|            if (dtdResourceName != null) {
  90|                final ClassLoader loader = getClass().getClassLoader();
  91|                final InputStream dtdIs = loader.getResourceAsStream(dtdResourceName);
  92|                inputSource = new InputSource(dtdIs);
  93|            }
  94|        }
  95|        return inputSource;
  96|    }
  97|
  98|    @Override
  99|    public void error(SAXParseException exception) throws SAXException {
 100|        throw exception;
 101|    }
 102|
 103|    /**
 104|     * Helper method to create {@code XMLReader}.
 105|     *
 106|     * @param handler the content handler
 107|     * @return new XMLReader instance
 108|     * @throws ParserConfigurationException if a parser cannot be created
 109|     * @throws SAXException for SAX errors
 110|     */
 111|    private static XMLReader createXmlReader(DefaultHandler handler)
 112|            throws SAXException, ParserConfigurationException {
 113|        final SAXParserFactory factory = SAXParserFactory.newInstance();
 114|        LoadExternalDtdFeatureProvider.setFeaturesBySystemProperty(factory);
 115|        factory.setValidating(true);
 116|        final XMLReader xmlReader = factory.newSAXParser().getXMLReader();
 117|        xmlReader.setContentHandler(handler);
 118|        xmlReader.setEntityResolver(handler);
 119|        xmlReader.setErrorHandler(handler);
 120|        return xmlReader;
 121|    }
 122|
 123|    /**
 124|     * Used for setting specific for secure java installations features to SAXParserFactory.
 125|     * Pulled out as a separate class in order to suppress Pitest mutations.
 126|     */
 127|    public static final class LoadExternalDtdFeatureProvider {
 128|
 129|        /** System property name to enable external DTD load. */
 130|        public static final String ENABLE_EXTERNAL_DTD_LOAD = "checkstyle.enableExternalDtdLoad";
 131|
 132|        /** Feature that enables loading external DTD when loading XML files. */
 133|        public static final String LOAD_EXTERNAL_DTD =
 134|                "http://apache.org/xml/features/nonvalidating/load-external-dtd";
 135|        /** Feature that enables including external general entities in XML files. */
 136|        public static final String EXTERNAL_GENERAL_ENTITIES =
 137|                "http://xml.org/sax/features/external-general-entities";
 138|        /** Feature that enables including external parameter entities in XML files. */
 139|        public static final String EXTERNAL_PARAMETER_ENTITIES =
 140|                "http://xml.org/sax/features/external-parameter-entities";
 141|
 142|        /** Stop instances being created. */
 143|        private LoadExternalDtdFeatureProvider() {
 144|        }
 145|
 146|        /**
 147|         * Configures SAXParserFactory with features required
 148|         * to use external DTD file loading, this is not activated by default to no allow
 149|         * usage of schema files that checkstyle do not know
 150|         * it is even security problem to allow files from outside.
 151|         *
 152|         * @param factory factory to be configured with special features
 153|         * @throws ParserConfigurationException if an error occurs
 154|         * @throws SAXException if an error occurs
 155|         */
 156|        public static void setFeaturesBySystemProperty(SAXParserFactory factory)
 157|                throws SAXException, ParserConfigurationException {
 158|
 159|            final boolean enableExternalDtdLoad = Boolean.parseBoolean(
 160|                System.getProperty(ENABLE_EXTERNAL_DTD_LOAD, "false"));
 161|
 162|            factory.setFeature(LOAD_EXTERNAL_DTD, enableExternalDtdLoad);
 163|            factory.setFeature(EXTERNAL_GENERAL_ENTITIES, enableExternalDtdLoad);
 164|            factory.setFeature(EXTERNAL_PARAMETER_ENTITIES, enableExternalDtdLoad);
 165|        }
 166|
 167|    }
 168|
